// Memo (HTTP Shortcuts, Android): compone il frammento e lo scrive in ingresso/<id>.md con un PUT (telefono/memo-ios.md, azioni 1-21).
// Nessun token qui: il PAT va nella variabile `pat` sul telefono. Solo testo e link (P3: gli allegati da Android non sono provati).
const URL_INGRESSO = 'https://api.github.com/repos/paol-imi/mnemosyne/contents/ingresso/';
const due = (n) => String(n).padStart(2, '0');
const adesso = new Date(); // un solo istante per id e registrato, nel fuso del telefono
const giorno = `${adesso.getFullYear()}${due(adesso.getMonth() + 1)}${due(adesso.getDate())}`;
const scarto = -adesso.getTimezoneOffset();
const fuso = scarto === 0 ? 'Z' : `${scarto < 0 ? '-' : '+'}${due(Math.floor(Math.abs(scarto) / 60))}:${due(Math.abs(scarto) % 60)}`;
const registrato = `${adesso.getFullYear()}-${due(adesso.getMonth() + 1)}-${due(adesso.getDate())}T${due(adesso.getHours())}:${due(adesso.getMinutes())}:${due(adesso.getSeconds())}${fuso}`;
const ALFABETO = 'abcdefghijklmnopqrstuvwxyz0123456789';
let xxxx = '';
for (let i = 0; i < 4; i++) xxxx += ALFABETO[Math.floor(Math.random() * ALFABETO.length)];
const id = `${giorno}-${due(adesso.getHours())}${due(adesso.getMinutes())}-${xxxx}`;
// Il testo condiviso (menu Condividi) o scritto nella finestra della variabile, intatto; vuoto va bene (B18).
// Sta solo nel corpo, mai nel frontmatter: virgolette, due punti e "---" non toccano lo YAML.
const testo = String(getVariable('testo') ?? '');
const file = `---\nregistrato: ${registrato}\ncanale: telefono\n---\n${testo}`;
const esito = sendHttpRequest(`${URL_INGRESSO}${id}.md`, {
  method: 'PUT',
  headers: {
    'Authorization': `Bearer ${getVariable('pat')}`,
    'Accept': 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({ message: `memo ${id}`, content: base64encode(file) }),
});
if (esito.status === 'success') {
  showToast('Salvato');
  // BLOCCO 7 (U7), spento finché P1 non passa: il fire della Routine "smista", con il token di fire nella variabile `fire`.
  // sendHttpRequest('https://api.anthropic.com/v1/claude_code/routines/<trig_ID>/fire', {
  //   method: 'POST',
  //   headers: { 'Authorization': `Bearer ${getVariable('fire')}`, 'anthropic-version': '2023-06-01',
  //     'anthropic-beta': 'experimental-cc-routine-2026-04-01', 'Content-Type': 'application/json' },
  //   body: JSON.stringify({ text: id }),
  // });
} else {
  copyToClipboard(testo);
  showDialog(`Non salvato (${esito.response ? esito.response.statusCode : 'rete'}): il testo è negli appunti.`, 'Memo');
}
